/**
 * states.states_index — every state, status and edge case in the spec, each a
 * direct link to its route. Generated by mapping over the spec, so a new entry
 * appears with no code change. Order (states_index.behaviour): List first, then
 * the remaining states in spec order, then statuses, then edge cases. A back
 * control beside the heading (copy.back) returns to /.
 */
import {
  type EdgeCase,
  type SpecState,
  firstFixtureWithStatus,
  spec,
  stateById,
} from '../spec/spec.ts';
import { Icon } from './Icon.tsx';
import { PROTOTYPE } from '../spec/copy.ts';
import { withPrototypeParams } from '../lib/url.ts';

const indexCopy = stateById.get('states_index')?.copy ?? {};

/** The list state's route, '/': copy.back links here and List leads the index. */
const HOME = stateById.get('list')?.route ?? '/';

function Row({ name, note, route, onNavigate }: {
  name: string;
  note: string;
  route: string;
  onNavigate: (route: string) => void;
}) {
  return (
    <li className="states__item">
      <a
        className="states__link"
        /* The href carries the prototype parameters too (?grey=1), so a
           copied or opened-in-new-tab link keeps the mode. */
        href={withPrototypeParams(route, window.location.search)}
        onClick={(event) => {
          event.preventDefault();
          onNavigate(route);
        }}
      >
        <span className="states__name">{name}</span>
        <span className="states__note">{note}</span>
        <code className="states__route">{route}</code>
      </a>
    </li>
  );
}

export function StatesIndex({
  onNavigate,
  grey,
  onGreyChange,
  chromeOff,
}: {
  onNavigate: (route: string) => void;
  /** prototypeAffordances.greyscalePlacement — the session's greyscale mode. */
  grey: boolean;
  onGreyChange: (grey: boolean) => void;
  /** ?chrome=off removes reviewer scaffolding, this control included. */
  chromeOff: boolean;
}) {
  const all = spec.states.filter((s: SpecState) => !s.isIndex);
  const states = [
    ...all.filter((s) => s.route === HOME),
    ...all.filter((s) => s.route !== HOME),
  ];

  return (
    <div className="states">
      <div className="states__head">
        <h1 className="states__headline">{indexCopy.headline}</h1>
        <a
          className="states__back"
          href={withPrototypeParams(HOME, window.location.search)}
          onClick={(event) => {
            event.preventDefault();
            onNavigate(HOME);
          }}
        >
          <Icon name="arrow-left" size="sm" />
          <span>{indexCopy.back}</span>
        </a>
      </div>
      <p className="states__body">{indexCopy.body}</p>

      {/* Reviewer scaffolding (prototypeAffordances), drawn in the bar's own
          style: the greyscale control and the reason it exists. */}
      {chromeOff ? null : (
      <div className="states__grey proto-panel">
        <label className="proto__toggle">
          <input
            type="checkbox"
            checked={grey}
            aria-describedby="greyscale-hint"
            onChange={(event) => onGreyChange(event.target.checked)}
          />
          <span className="proto__key">{PROTOTYPE.greyscaleLabel}</span>
        </label>
        <span className="proto__hint" id="greyscale-hint">
          {PROTOTYPE.greyscaleHint}
        </span>
      </div>
      )}

      <ul className="states__list">
        {states.map((state) => (
          <Row
            key={state.id}
            name={state.name}
            note={state.trigger}
            route={state.route}
            onNavigate={onNavigate}
          />
        ))}

        {spec.statuses.map((status) => {
          const fixture = firstFixtureWithStatus(status.id);
          if (!fixture) return null;
          return (
            <Row
              key={status.id}
              name={status.label}
              note={status.listTreatment.badge}
              route={`/?tx=${fixture.id}`}
              onNavigate={onNavigate}
            />
          );
        })}

        {spec.edgeCases.map((edge: EdgeCase) => (
          <Row
            key={edge.id}
            name={edge.requirement}
            note={edge.rule}
            route={edge.route}
            onNavigate={onNavigate}
          />
        ))}
      </ul>
    </div>
  );
}
